                # BFS to find connected 5s
                from collections import deque
                q = deque([(r,c)])
                visited[r,c] = True
                cells = [(r,c)]
                while q:
                    cr,cc = q.popleft()
                    for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr,nc = cr+dr, cc+dc
                        if 0<=nr<rows and 0<=nc<cols and not visited[nr,nc] and g[nr,nc] == 5:
